export { descriptionId, view } from "../textarea";
export type { TextareaAttributes, ViewConfig } from "../textarea";

export {
  shadcnTextareaClassName,
  shadcnTextareaDescriptionClassName,
  shadcnTextareaFieldClassName,
  shadcnTextareaLabelClassName,
} from "./view";

export {
  descriptionClassName as shadcnTextareaDescriptionClassName,
  fieldClassName as shadcnTextareaFieldClassName,
  labelClassName as shadcnTextareaLabelClassName,
  textareaClassName as shadcnTextareaClassName,
} from "../textarea/view";

import { describe, expect, test } from "vitest";

import * as Textarea from "./index";

describe("shadcn Textarea registry view", () => {
  test("reuses the Foldkit Textarea view contract", () => {
    expect(Textarea.view).toBeTypeOf("function");
    expect(Textarea.descriptionId).toBeTypeOf("function");
    expect(Textarea.shadcnTextareaClassName).toContain("rounded");
  });
});
